def fix(g):
    n=len(g); R=range(n)
    for c in sorted(set(x for r in g for x in r)):
        if all(g[i][j]!=c or (g[n-1-i][j]==c and g[i][n-1-j]==c) for i in R for j in R):
            continue  # symmetric color, not noise
        # noise candidate: cells of c breaking symmetry
        noise={(i,j) for i in R for j in R if g[i][j]==c and (g[n-1-i][j]!=c or g[i][n-1-j]!=c)}
        if not noise: continue
        out=[r[:] for r in g]
        ok=True
        for i,j in noise:
            val=None
            for a,b in ((n-1-i,j),(i,n-1-j),(n-1-i,n-1-j),(j,i)):
                if g[a][b]!=c and (a,b) not in noise:
                    val=g[a][b]; break
            if val is None: ok=False; break
            out[i][j]=val
        if ok:
            return out
    return None
